import { loadFont as loadHead } from "@remotion/google-fonts/Anton";
import { loadFont as loadSerif } from "@remotion/google-fonts/Cinzel";
import { loadFont as loadSans } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// IGREJA VIDA NOVA EM CRISTO (Belford Roxo) — 4º cliente do Leonardo (igrejas), pedido 27/10. Convite falado pelo pastor
// (takes video-2..5 cortados em fala.mp4, 77,3 s), alternando com cenas desenhadas, cenas de culto e fotos da igreja.
// Identidade do painel atrás do pastor e das artes: azul royal, marinho, onda dourada, azul claro de destaque, chama
// laranja→vermelha com cruz sobre a Bíblia aberta. Letra condensada pesada (Anton) como nas artes; Cinzel no nome.
// Padrão do Leonardo: botão "Clica aqui agora" pulsando nos primeiros 15 s, texto do peito para baixo e fora da faixa
// de baixo, transições próprias desta igreja (página virando, luz da chama, cartão, empurrão, círculo de luz).

const { fontFamily: HEAD } = loadHead("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SERIF } = loadSerif("normal", { weights: ["600", "700"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SANS } = loadSans("normal", { weights: ["600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const VNC_FPS = 30;
const OFF = 0.3; // a voz começa aos 0,3 s
const VOICE_END = 77.29;
const END = 74.0; // cartão final (tempo da voz)
export const VNC_FRAMES = Math.round((VOICE_END + OFF + 2.3) * VNC_FPS);

const ROYAL = "#1D3AB0";
const NAVY = "#0E1A5E";
const DEEP = "#0A1240";
const GOLD = "#E8B64A";
const SKY = "#5CC8F7";
const FLAME_Y = "#FFC63A";
const FLAME_O = "#F7871F";
const FLAME_R = "#E32A2A";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const SOFT = Easing.bezier(0.33, 0, 0.2, 1);
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const ease = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
// mola com pouco passe (≈4 %)
const spr = (t: number, a: number, d = 0.5) => {
  const x = Math.max(0, Math.min(1, (t - a) / d));
  return 1 - Math.exp(-6 * x) * Math.cos(4.2 * x) * (1 - x) - 0 * x;
};
const SHADOW = "0 4px 22px rgba(4,8,30,0.75), 0 0 4px rgba(4,8,30,0.6)";
const vsrc = (f: string) => staticFile(`leonardo-vnc/${f}`);

// ─── lettering: palavra que sobe da linha (máscara), palavra-chave em bloco royal com filete dourado ───
type W = [string, number, boolean?];
const Line: React.FC<{ t: number; items: W[]; size: number; width?: number }> = ({ t, items, size, width = 860 }) => (
  <div style={{ width, display: "flex", flexWrap: "wrap", justifyContent: "center", alignItems: "center", columnGap: size * 0.22, rowGap: size * 0.14 }}>
    {items.map(([w, at, tag], i) => {
      // cabe na coluna central (840 px): a letra encolhe nas frases longas
      const fs = Math.min(size, 820 / (w.length * 0.47 + (tag ? 0.4 : 0)));
      const e = ease(t, at, 0.42);
      const p = tag ? interpolate(t, [at, at + 0.38], [0, 1], { ...cl, easing: OUT }) : 1;
      return (
        <div key={i} style={{ overflow: "hidden", padding: tag ? 0 : "0 4px", position: "relative" }}>
          <div
            style={{
              fontFamily: HEAD,
              fontSize: fs,
              lineHeight: 1.24,
              color: "#FFFFFF",
              textTransform: "uppercase",
              whiteSpace: "nowrap",
              letterSpacing: "0.01em",
              transform: `translateY(${((1 - e) * 105).toFixed(1)}%)`,
              textShadow: tag ? "none" : SHADOW,
              background: tag ? ROYAL : undefined,
              padding: tag ? `${fs * 0.04}px ${fs * 0.2}px ${fs * 0.06}px` : undefined,
              boxShadow: tag ? `inset 0 -${Math.round(fs * 0.08)}px 0 ${GOLD}` : undefined,
              clipPath: tag ? `inset(0 ${((1 - p) * 100).toFixed(1)}% 0 0)` : undefined,
              opacity: t >= at ? 1 : 0,
            }}
          >
            {w}
          </div>
        </div>
      );
    })}
  </div>
);
// grupos que se revezam no mesmo lugar: o anterior some inteiro antes do próximo entrar
type G = { a: number; b?: number; lines: { items: W[]; size: number }[] };
const DY = React.createContext(0);
const Lettering: React.FC<{ t: number; groups: G[]; top: number; gap?: number }> = ({ t, groups, top: top0, gap = 14 }) => {
  const dy = React.useContext(DY);
  const top = top0 < 1300 ? top0 + dy : top0;
  return (
  <>
    {groups.map((g, i) => {
      const b = g.b ?? (groups[i + 1] ? groups[i + 1].a - 0.06 : 1e9);
      if (t < g.a - 0.02 || t >= b) return null;
      const out = 1 - lin(t, b - 0.14, b);
      return (
        <div key={i} style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap, opacity: out }}>
          {g.lines.map((l, j) => (
            <Line key={j} t={t} items={l.items} size={l.size} />
          ))}
        </div>
      );
    })}
  </>
  );
};

// ─── fundos ───
const Plain: React.FC<{ dark?: boolean }> = ({ dark }) => (
  <AbsoluteFill style={{ background: dark ? `radial-gradient(ellipse 90% 70% at 50% 40%, #16204F 0%, ${DEEP} 70%, #060A24 100%)` : `radial-gradient(ellipse 90% 70% at 50% 38%, #2747C4 0%, ${ROYAL} 45%, ${NAVY} 100%)` }} />
);
// véu para o texto ler embaixo da imagem
const Veil: React.FC<{ k?: number }> = ({ k = 1 }) => (
  <AbsoluteFill style={{ background: `linear-gradient(180deg, rgba(10,18,64,${0.25 * k}) 0%, rgba(10,18,64,0) 22%, rgba(10,18,64,0) 44%, rgba(10,18,64,${0.6 * k}) 64%, rgba(10,18,64,${0.8 * k}) 100%)` }} />
);

// ─── a fala do pastor: enquadramento muda a cada corte de pausa (vira aproximação, não tropeço) ───
const CUTS = [0, 9.73, 18.32, 20.9, 22.61, 26.42, 27.69, 36.06, 45.24, 46.38, 53.74, 55.77, 57.62, 59.23, 61.89, 62.16, 63.97, 65.14, 75.79];
const ZOOMS = [1.06, 1.16, 1.08, 1.2, 1.1, 1.18, 1.05, 1.15, 1.1, 1.2, 1.07, 1.17, 1.09, 1.19, 1.06, 1.14, 1.1, 1.18, 1.08];
const Pastor: React.FC<{ tv: number; a: number; b: number }> = ({ tv, a, b }) => {
  let idx = 0;
  for (let i = 0; i < CUTS.length; i++) if (CUTS[i] <= tv + 1e-3) idx = i;
  const s = ZOOMS[idx] + 0.035 * lin(tv, a, b);
  return (
    <AbsoluteFill style={{ background: NAVY, overflow: "hidden" }}>
      <OffthreadVideo src={vsrc("fala.mp4")} muted style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", transform: `scale(${s.toFixed(4)})`, transformOrigin: tv < 22.6 ? "50% 50%" : "50% 22%", filter: "contrast(1.04) saturate(1.06)" }} />
      <Veil k={0.9} />
    </AbsoluteFill>
  );
};
// cena de culto em tela cheia, começando a rodar antes da troca
const Clip: React.FC<{ tv: number; a: number; b: number; src: string; from?: number; z?: [number, number]; pos?: string; origin?: string }> = ({ tv, a, b, src, from = 0, z = [1.04, 1.14], pos = "50% 50%", origin = "50% 45%" }) => (
  <AbsoluteFill style={{ background: "#000", overflow: "hidden" }}>
    <Sequence from={Math.round((a + OFF - 0.4) * VNC_FPS)} layout="none">
      <OffthreadVideo src={vsrc(src)} trimBefore={Math.round(from * VNC_FPS)} muted style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, transform: `scale(${(z[0] + (z[1] - z[0]) * lin(tv, a, b)).toFixed(4)})`, transformOrigin: origin }} />
    </Sequence>
    <Veil />
  </AbsoluteFill>
);
const Photo: React.FC<{ tv: number; a: number; b: number; src: string; z?: [number, number]; origin?: string; dy?: number }> = ({ tv, a, b, src, z = [1.03, 1.12], origin = "50% 40%", dy = 0 }) => (
  <AbsoluteFill style={{ background: NAVY, overflow: "hidden" }}>
    <Img src={vsrc(src)} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", transform: `translateY(${(dy * lin(tv, a, b)).toFixed(1)}px) scale(${(z[0] + (z[1] - z[0]) * lin(tv, a, b)).toFixed(4)})`, transformOrigin: origin }} />
    <Veil />
  </AbsoluteFill>
);

// ─── peças desenhadas ───
// o símbolo: Bíblia aberta, chama e cruz (redesenhado do painel da igreja)
const Symbol: React.FC<{ t: number; at: number; w: number; flame?: number }> = ({ t, at, w, flame }) => {
  const book = lin(t, at, at + 0.7);
  const fl = flame ?? ease(t, at + 0.35, 0.6);
  const cross = ease(t, at + 0.75, 0.4);
  const flick = 1 + 0.025 * Math.sin(t * 9) + 0.015 * Math.sin(t * 13.7);
  const pages = (side: 1 | -1) =>
    [0, 1, 2].map((i) => {
      const y0 = 140 + i * 12;
      const d = `M100,${y0} C${100 - 22 * side},${y0 - 22} ${100 - 56 * side},${y0 - 28} ${100 - (82 + i * 4) * side},${y0 - 18}`;
      return <path key={`${side}${i}`} d={d} fill="none" stroke="#FFFFFF" strokeWidth={7 - i} strokeLinecap="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - Math.min(1, Math.max(0, book * 1.4 - i * 0.2))} />;
    });
  return (
    <svg width={w} height={w} viewBox="0 0 200 200" style={{ overflow: "visible" }}>
      <defs>
        <linearGradient id="vncFlame" x1="0.2" y1="1" x2="0.8" y2="0">
          <stop offset="0" stopColor={FLAME_Y} />
          <stop offset="0.45" stopColor={FLAME_O} />
          <stop offset="1" stopColor={FLAME_R} />
        </linearGradient>
      </defs>
      <g transform={`translate(100 140) scale(${(fl * flick).toFixed(4)} ${(fl * (2 - flick)).toFixed(4)}) translate(-100 -140)`} opacity={Math.min(1, fl * 1.6)}>
        <path d="M100,140 C68,132 60,102 76,76 C80,94 90,100 92,100 C86,70 100,42 126,18 C118,50 142,66 142,98 C142,124 124,138 100,140 Z" fill="url(#vncFlame)" />
        <path d="M100,138 C84,132 80,116 88,102 C92,112 98,114 100,114 C98,98 106,84 118,74 C116,92 128,100 126,116 C124,130 112,138 100,138 Z" fill={FLAME_Y} opacity={0.75} />
      </g>
      <g opacity={cross} transform={`translate(0 ${((1 - cross) * 14).toFixed(1)})`}>
        <rect x={96.5} y={50} width={7} height={100} rx={1.5} fill={NAVY} />
        <rect x={82} y={70} width={36} height={7} rx={1.5} fill={NAVY} />
      </g>
      {pages(1)}
      {pages(-1)}
    </svg>
  );
};
const Name: React.FC<{ t: number; at: number; scale?: number }> = ({ t, at, scale = 1 }) => {
  const a = ease(t, at, 0.45);
  const b = ease(t, at + 0.18, 0.5);
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 * scale }}>
      <div style={{ overflow: "hidden" }}>
        <div style={{ fontFamily: HEAD, fontSize: 64 * scale, letterSpacing: "0.32em", paddingLeft: "0.32em", color: "#FFFFFF", transform: `translateY(${((1 - a) * 105).toFixed(1)}%)` }}>IGREJA</div>
      </div>
      <div style={{ overflow: "hidden" }}>
        <div style={{ fontFamily: SERIF, fontWeight: 700, fontSize: 70 * scale, color: "#FFFFFF", whiteSpace: "nowrap", transform: `translateY(${((1 - b) * 105).toFixed(1)}%)` }}>VIDA NOVA EM CRISTO</div>
      </div>
      <div style={{ height: 6 * scale, width: 560 * scale * b, background: GOLD, borderRadius: 3, marginTop: 10 * scale }} />
    </div>
  );
};
const Hand: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="#FFFFFF" stroke={NAVY} strokeWidth={1.1} strokeLinejoin="round">
    <path d="M9 11V4.5a1.5 1.5 0 0 1 3 0V10l.5-.1V8.6a1.5 1.5 0 0 1 3 .1v1.6a1.5 1.5 0 0 1 3 .2v1.2a1.4 1.4 0 0 1 2.6.6V16c0 3.3-2.4 6-5.8 6h-1.6c-1.9 0-3.4-.8-4.5-2.3L5 15.4a1.6 1.6 0 0 1 2.4-2.1L9 14.8z" />
  </svg>
);
// botão de convite (padrão do Leonardo): pulsa na batida, com anel saindo
const Button: React.FC<{ t: number; at: number; top: number; scale?: number; out?: number; small?: string; big?: string }> = ({ t, at, top, scale = 0.8, out, small = "Queremos te acolher", big = "Clica aqui agora" }) => {
  if (t < at) return null;
  const e = ease(t, at, 0.5);
  const off = out === undefined ? 1 : 1 - lin(t, out - 0.25, out);
  if (off <= 0) return null;
  const beat = (t - at) % 1.0;
  const pulse = 1 + 0.05 * Math.sin(Math.PI * Math.min(1, beat / 0.45)) * (beat < 0.45 ? 1 : 0);
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", justifyContent: "center", opacity: off * Math.min(1, e * 1.6) }}>
      <div style={{ position: "relative", transform: `translateY(${((1 - e) * 60).toFixed(0)}px) scale(${(scale * pulse).toFixed(4)})`, transformOrigin: "50% 50%" }}>
        <div style={{ position: "absolute", inset: 0, borderRadius: 999, border: `5px solid ${GOLD}`, transform: `scale(${(1 + beat * 0.16).toFixed(3)}, ${(1 + beat * 0.45).toFixed(3)})`, opacity: (1 - beat) * 0.75 }} />
        <div style={{ display: "flex", alignItems: "center", gap: 24, background: "#FFFFFF", borderRadius: 999, padding: "20px 44px 22px 54px", boxShadow: `0 16px 40px rgba(4,8,30,0.5), 0 0 0 5px ${GOLD}` }}>
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
            <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 28, letterSpacing: "0.14em", color: ROYAL, textTransform: "uppercase", whiteSpace: "nowrap" }}>{small}</div>
            <div style={{ fontFamily: HEAD, fontSize: 66, lineHeight: 1.08, color: NAVY, textTransform: "uppercase", whiteSpace: "nowrap" }}>{big}</div>
          </div>
          <div style={{ width: 84, height: 84, borderRadius: 42, background: ROYAL, display: "flex", alignItems: "center", justifyContent: "center" }}>
            <Hand s={58} />
          </div>
        </div>
      </div>
    </div>
  );
};

// casa com tempestade que se abre em luz (o problema e o desejo de voltar para Deus)
const StormHouse: React.FC<{ tv: number }> = ({ tv }) => {
  const enter = ease(tv, 6.05, 0.6);
  const storm = 1 - lin(tv, 11.6, 13.0); // a nuvem vai embora no "reaproximar"
  const light = lin(tv, 12.4, 14.0);
  const cloudIn = ease(tv, 6.4, 0.7);
  const bolt = (tv > 7.75 && tv < 7.9) || (tv > 9.35 && tv < 9.48) ? 1 : 0;
  const cam = 1.0 + 0.06 * lin(tv, 6.05, 16.3);
  const drops = Array.from({ length: 26 }, (_, i) => i);
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <AbsoluteFill style={{ background: `radial-gradient(ellipse 90% 70% at 50% 34%, #16204F 0%, ${DEEP} 70%, #060A24 100%)` }} />
      <AbsoluteFill style={{ opacity: light, background: `radial-gradient(ellipse 80% 60% at 50% 18%, #FFE7A8 0%, ${GOLD} 18%, #3354D1 52%, ${ROYAL} 75%, ${NAVY} 100%)` }} />
      <AbsoluteFill style={{ opacity: bolt * storm * 0.35, background: "#AFC4FF" }} />
      <AbsoluteFill style={{ transform: `scale(${cam.toFixed(4)})`, transformOrigin: "50% 45%" }}>
        {/* raios de luz descendo */}
        <svg width={1080} height={1920} style={{ position: "absolute", inset: 0, opacity: light * 0.55 }}>
          {[-3, -2, -1, 0, 1, 2, 3].map((k) => (
            <polygon key={k} points={`${540 + k * 30},-40 ${540 + k * 34},-40 ${540 + k * 150 + 40},900 ${540 + k * 150 - 40},900`} fill="#FFF3CF" opacity={0.18 + 0.05 * Math.sin(tv * 2 + k)} />
          ))}
        </svg>
        {/* casa */}
        <svg width={1080} height={1920} style={{ position: "absolute", inset: 0 }}>
          <g transform={`translate(540 ${(820 + (1 - enter) * 120).toFixed(0)})`} opacity={enter}>
            <path d="M-210,0 L0,-190 L210,0" fill="none" stroke="#FFFFFF" strokeWidth={22} strokeLinecap="round" strokeLinejoin="round" />
            <path d="M-160,-40 L-160,200 L160,200 L160,-40" fill="none" stroke="#FFFFFF" strokeWidth={22} strokeLinejoin="round" />
            <rect x={-50} y={80} width={100} height={120} rx={8} fill="none" stroke="#FFFFFF" strokeWidth={18} />
            <rect x={-118} y={10} width={58} height={58} rx={6} fill={light > 0.2 ? FLAME_Y : "none"} opacity={0.4 + 0.6 * light} stroke="#FFFFFF" strokeWidth={14} />
            <rect x={60} y={10} width={58} height={58} rx={6} fill={light > 0.2 ? FLAME_Y : "none"} opacity={0.4 + 0.6 * light} stroke="#FFFFFF" strokeWidth={14} />
          </g>
          {/* nuvem, chuva e raio */}
          <g transform={`translate(${(540 + (1 - storm) * 0).toFixed(0)} ${(470 - (1 - cloudIn) * 260 - (1 - storm) * 420).toFixed(0)})`} opacity={cloudIn * storm}>
            {drops.map((i) => {
              const x = -230 + (i % 13) * 38 + (i > 12 ? 19 : 0);
              const ph = ((tv * 2.2 + i * 0.37) % 1 + 1) % 1;
              return <line key={i} x1={x} y1={60 + ph * 300} x2={x - 10} y2={100 + ph * 300} stroke={SKY} strokeWidth={7} strokeLinecap="round" opacity={0.85 * (1 - ph)} />;
            })}
            <path d="M-250,60 C-320,60 -320,-40 -240,-40 C-240,-130 -110,-150 -70,-80 C-30,-170 140,-160 150,-50 C240,-70 290,60 200,60 Z" fill="#3A4472" stroke="#C9D2F0" strokeWidth={8} />
            <path d="M10,40 L-30,150 L20,150 L-20,260" fill="none" stroke={FLAME_Y} strokeWidth={14} strokeLinejoin="round" strokeLinecap="round" opacity={bolt} />
          </g>
        </svg>
        {/* a chama acende sobre a casa */}
        <div style={{ position: "absolute", left: 410, top: 330, opacity: light }}>
          <Symbol t={tv} at={13.2} w={260} />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// "ninguém é apenas mais um": pontos iguais, um deles acende
const Dots: React.FC<{ tv: number }> = ({ tv }) => {
  const R = 7, C = 5;
  const hi = ease(tv, 34.9, 0.6);
  const cam = 1 + 0.25 * ease(tv, 34.9, 1.1);
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <Plain />
      <AbsoluteFill style={{ transform: `scale(${cam.toFixed(4)})`, transformOrigin: "50% 37%" }}>
        {Array.from({ length: R * C }, (_, i) => {
          const r = Math.floor(i / C), c = i % C;
          const me = r === 3 && c === 2;
          const at = 33.45 + (r + c) * 0.05;
          const e = ease(tv, at, 0.4);
          const x = 540 + (c - 2) * 150, y = 260 + r * 130;
          const s = me ? 1 + 0.9 * hi : 1 - 0.15 * hi;
          return (
            <div key={i} style={{ position: "absolute", left: x - 34, top: y - 34, width: 68, height: 68, borderRadius: 34, background: me && hi > 0 ? GOLD : "rgba(255,255,255,0.85)", opacity: e * (me ? 1 : 1 - 0.55 * hi), transform: `scale(${(e * s).toFixed(3)})`, boxShadow: me ? `0 0 ${(40 * hi).toFixed(0)}px rgba(232,182,74,0.7)` : undefined }} />
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// chama crescendo (fortalecer a fé)
const Faith: React.FC<{ tv: number }> = ({ tv }) => {
  const g = ease(tv, 39.1, 0.9);
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <Plain />
      <AbsoluteFill style={{ background: `radial-gradient(circle at 50% 36%, rgba(255,198,58,${(0.35 * g).toFixed(3)}) 0%, rgba(255,198,58,0) 38%)` }} />
      <div style={{ position: "absolute", left: 540 - 300, top: 120, transform: `scale(${(0.7 + 0.45 * g).toFixed(3)})`, transformOrigin: "50% 80%" }}>
        <Symbol t={tv} at={39.0} w={600} flame={0.25 + 0.75 * g} />
      </div>
    </AbsoluteFill>
  );
};

// três palavras batendo: restauração, cura, libertação (luz atrás de cada uma)
const Three: React.FC<{ tv: number }> = ({ tv }) => {
  const W3: [string, number, string][] = [
    ["Restauração", 51.27, ROYAL],
    ["Cura", 52.25, "#1A2E8F"],
    ["Libertação", 52.87, NAVY],
  ];
  let k = 0;
  for (let i = 0; i < 3; i++) if (tv >= W3[i][1] - 0.02) k = i;
  const [w, at] = W3[k];
  const e = ease(tv, at, 0.35);
  const intro = ease(tv, 50.55, 0.5);
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <AbsoluteFill style={{ background: W3[k][2] }} />
      {/* cada palavra entra com uma faixa dourada passando */}
      <div style={{ position: "absolute", left: 540 - 170, top: 270, opacity: intro }}>
        <Symbol t={tv} at={50.4} w={340} />
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1110 - 8, height: 16, background: GOLD, transform: `scaleX(${ease(tv, at - 0.05, 0.4).toFixed(3)})` }} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 760, display: "flex", flexDirection: "column", alignItems: "center", gap: 20 }}>
        <div style={{ overflow: "hidden", opacity: intro }}>
          <div style={{ fontFamily: SANS, fontWeight: 800, fontSize: 40, letterSpacing: "0.3em", paddingLeft: "0.3em", color: SKY, transform: `translateY(${((1 - intro) * 105).toFixed(1)}%)` }}>CREMOS EM</div>
