const D = 0.4;
// as entradas desta igreja (nenhuma igual à da Lagoinha, Brasa Viva, Rhema ou IEQ)
const tinStyle = (type: Tin, p: number): React.CSSProperties => {
  const e = SOFT(Math.min(1, Math.max(0, p)));
  if (type === "page") return { transform: `perspective(2200px) rotateY(${((1 - e) * -82).toFixed(2)}deg)`, transformOrigin: "100% 50%", opacity: Math.min(1, e * 3) };
  if (type === "flame") return { clipPath: `ellipse(${(e * 95).toFixed(1)}% ${(e * 150).toFixed(1)}% at 50% 100%)` };
  if (type === "card") return { transform: `translateY(${((1 - e) * 300).toFixed(0)}px) scale(${(0.7 + 0.3 * e).toFixed(4)})`, borderRadius: (1 - e) * 80, overflow: "hidden", opacity: Math.min(1, e * 2.5) };
  if (type === "push") return { transform: `translateX(${((1 - e) * 1080).toFixed(0)}px)` };
  if (type === "light") return { clipPath: `circle(${(e * 120).toFixed(1)}% at 50% 42%)` };
  return {};
};
// o que sai, sai acelerando (empurrão leva a cena anterior junto)
const outStyle = (type: Tin, p: number): React.CSSProperties => {
  const e = SOFT(Math.min(1, Math.max(0, p)));
  if (type === "push") return { transform: `translateX(${(-e * 1080).toFixed(0)}px)` };
  if (type === "page") return { filter: `brightness(${(1 - 0.35 * e).toFixed(3)})` };
  if (type === "card") return { transform: `scale(${(1 - 0.08 * e).toFixed(4)})`, filter: `brightness(${(1 - 0.4 * e).toFixed(3)})` };
  return {};
};
// borda das entradas: anel dourado na luz, borda de chama
const Edge: React.FC<{ type: Tin; p: number }> = ({ type, p }) => {
  if (p <= 0 || p >= 1) return null;
  const e = SOFT(p);
  if (type === "light") return <div style={{ position: "absolute", left: 540, top: 1920 * 0.42, width: 0, height: 0 }}><div style={{ position: "absolute", left: -(e * 1.2 * 2203) / 2, top: -(e * 1.2 * 2203) / 2, width: e * 1.2 * 2203, height: e * 1.2 * 2203, borderRadius: "50%", border: `14px solid ${GOLD}`, boxShadow: "0 0 30px rgba(232,182,74,0.6)", opacity: 1 - e * 0.5 }} /></div>;
  if (type === "flame") {
    const rx = e * 0.95 * 1080 * 1.0, ry = e * 1.5 * 1920 * 0.62;
    return <svg width={1080} height={1920} style={{ position: "absolute", inset: 0 }}><ellipse cx={540} cy={1920} rx={rx} ry={ry * 1.62} fill="none" stroke={FLAME_O} strokeWidth={16} opacity={0.9} /></svg>;
  }
  return null;
};

export const VncConvite: React.FC<{ cta?: boolean; dy?: number }> = ({ cta = true, dy = 0 }) => {
  const f = useCurrentFrame();
  const t = f / VNC_FPS;
  const tv = t - OFF;
  const endT = VNC_FRAMES / VNC_FPS - OFF;
  return (
    <DY.Provider value={dy}>
    <AbsoluteFill style={{ background: NAVY }}>
      {SCENES.map((s, i) => {
        const next = SCENES[i + 1];
        const b = next ? next.a : endT;
        const vis0 = s.tin === "none" ? s.a : s.a - D / 2;
        const vis1 = next ? b + D / 2 : endT + 1;
        if (tv < vis0 || tv >= vis1) return null;
        const p = s.tin === "none" ? 1 : (tv - (s.a - D / 2)) / D;
        const po = next ? (tv - (b - D / 2)) / D : 0;
        const st: React.CSSProperties = p < 1 ? tinStyle(s.tin, p) : po > 0 && next ? outStyle(next.tin, po) : {};
        return (
          <AbsoluteFill key={i} style={st}>
            {s.render(tv, s.a, b)}
          </AbsoluteFill>
        );
      })}
      {SCENES.map((s, i) => (s.tin === "light" || s.tin === "flame" ? <Edge key={`e${i}`} type={s.tin} p={(tv - (s.a - D / 2)) / D} /> : null))}
      {/* botão de convite nos primeiros 15 s (padrão do Leonardo) */}
      {cta ? <Button t={tv} at={0.55} top={1350} out={14.75} /> : null}
      <AbsoluteFill style={{ background: "#000", opacity: interpolate(t, [VNC_FRAMES / VNC_FPS - 0.4, VNC_FRAMES / VNC_FPS], [0, 1], cl), pointerEvents: "none" }} />
    </AbsoluteFill>
    </DY.Provider>
  );
};
